-- ============================================================
-- 5-ftq-oktober-2026.sql — DATA PERCOBAAN: FTQ Oktober 2026
-- Sumber: New_Dash_FTQ_FA_Oct_fix.xlsx (951 baris, total qty 1020)
-- Jalankan di Supabase: SQL Editor -> New query -> tempel semua -> Run
-- (setelah 1-setup.sql dan 4-kolom-baru.sql). Aman: bila data Oktober 2026 sudah ada, skrip berhenti
-- dengan pesan dan TIDAK menambah apa pun, jadi tidak akan dobel.
-- Untuk menghapus data percobaan ini:
--   delete from public.ftq where date between '2026-10-01' and '2026-10-31';
-- ============================================================

do $$
begin
  if exists (select 1 from public.ftq where date between '2026-10-01' and '2026-10-31') then
    raise exception 'Data FTQ Oktober 2026 sudah ada di database. Tidak ada yang ditambahkan.';
  end if;
end $$;





